  <% if bot.errors.any? %>
    <div role="alert">
      <%= bot.errors.full_messages.to_sentence %>
    </div>
  <% end %>

  <div class="align-center center avatar__form gap" data-controller="upload-preview">
    <div class="avatar"><%= image_tag bot.avatar.attached? ? bot.avatar : "default-avatar.svg", aria: { hidden: "true" }, data: { upload_preview_target: "image" } %></div>
    <label class="btn input--file">
      <%= image_tag "camera.svg", aria: { hidden: "true" }, size: 20 %>
      <%= form.file_field :avatar, class: "input", accept: "image/*", data: { upload_preview_target: "input", action: "upload-preview#previewImage" } %>
      <span class="for-screen-reader">Upload avatar</span>
    </label>
  </div>

  <%= form.label :name, "Name the bot" %>
  <%= form.text_field :name, class: "input txt-large", required: true, autofocus: true, autocomplete: "off" %>

  <%= form.label :webhook_url, "Webhook URL" %>
  <%= form.url_field :webhook_url, class: "input", autocomplete: "off" %>

  <%= form.button "Save changes", class: "btn btn--reversed center" %>
